def pq_encode(vector, codebooks, subvector_dim):
    codes = []
    for i, km in enumerate(codebooks):
        chunk = vector[i*subvector_dim:(i+1)*subvector_dim].reshape(1, -1)
        codes.append(km.predict(chunk)[0])
    return codes   # e.g. [12, 200, 88, 5, 240, 3, 176, 61]

